const photoModal = document.getElementById('photoModal');
const photoGrid = document.getElementById('photoModalGrid');
const photoTitle = document.getElementById('photoModalTitle');
const videoModal = document.getElementById('videoModal');
const videoFrame = document.getElementById('videoModalFrame');
const videoTitle = document.getElementById('videoModalTitle');
const videoLink = document.getElementById('videoModalLink');

function openModal(modal) {
  modal?.classList.add('is-open');
  modal?.setAttribute('aria-hidden','false');
  document.body.classList.add('v13-modal-open');
}
function closeModal() {
  document.querySelectorAll('.v13-modal.is-open').forEach(m => {
    m.classList.remove('is-open');
    m.setAttribute('aria-hidden','true');
  });
  if(videoFrame) videoFrame.src = '';
  document.body.classList.remove('v13-modal-open');
}
document.querySelectorAll('[data-modal-close]').forEach(el => el.addEventListener('click', closeModal));
document.addEventListener('keydown', e => { if(e.key === 'Escape') closeModal(); });

document.querySelectorAll('.v13-album').forEach(btn => btn.addEventListener('click', () => {
  const album = albums[btn.dataset.album];
  if(!album) return;
  photoTitle.textContent = album.title;
  photoGrid.innerHTML = album.photos.map(p => `<figure><img src="${p.src}" alt="${p.alt || ''}" loading="lazy"></figure>`).join('');
  openModal(photoModal);
}));

document.querySelectorAll('.v13-video-card').forEach(btn => btn.addEventListener('click', () => {
  const id = btn.dataset.video;
  videoTitle.textContent = btn.dataset.title || 'Событие';
  videoFrame.src = `https://rutube.ru/play/embed/${id}`;
  videoLink.href = btn.dataset.link || `https://rutube.ru/video/${id}/`;
  openModal(videoModal);
}));

document.getElementById('atmoBtn')?.addEventListener('click', () => {
  document.querySelector('#media')?.scrollIntoView({behavior:'smooth'});
});

document.getElementById('bookingForm')?.addEventListener('submit', e => {
  e.preventDefault();
  const name = document.getElementById('clientName')?.value.trim() || 'Не указано';
  const contact = document.getElementById('clientContact')?.value.trim() || 'Не указано';
  const type = document.getElementById('eventType')?.value || 'Мероприятие';
  const date = document.getElementById('eventDate')?.value || 'дата уточняется';
  const guests = document.getElementById('guests')?.value || 'не указано';
  const vocal = document.getElementById('vocal')?.checked ? 'да' : 'нет';

  const text = `Здравствуйте, Влад! Хочу узнать свободна ли дата.\n\nИмя: ${name}\nКонтакт: ${contact}\nМероприятие: ${type}\nДата: ${date}\nГостей: ${guests}\nЖивой вокал: ${vocal}`;
  const phone = '79243399940';
  const encoded = encodeURIComponent(text);
  const isMobile = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
  const url = isMobile
    ? `https://wa.me/${phone}?text=${encoded}`
    : `https://web.whatsapp.com/send?phone=${phone}&text=${encoded}`;
  window.location.href = url;
});

const scrollTopBtn = document.getElementById('scrollTopBtn');
function syncScrollTop() {
  scrollTopBtn?.classList.toggle('is-visible', window.scrollY > 420);
}
window.addEventListener('scroll', syncScrollTop, {passive:true});
syncScrollTop();
scrollTopBtn?.addEventListener('click', () => window.scrollTo({top:0,behavior:'smooth'}));


// Reviews lightbox
const reviewModal=document.getElementById('reviewModal');
const reviewModalImage=document.getElementById('reviewModalImage');
const reviewModalTitle=document.getElementById('reviewModalTitle');

function closeReviewModal(){
  reviewModal?.classList.remove('is-open');
  reviewModal?.setAttribute('aria-hidden','true');
  if(reviewModalImage) reviewModalImage.src='';
  document.body.classList.remove('modal-open');
}

document.querySelectorAll('.review-card-v13').forEach(card=>{
  card.addEventListener('click',()=>{
    if(!reviewModal || !reviewModalImage) return;
    reviewModalImage.src=card.dataset.review;
    reviewModalImage.alt='Отзыв — '+(card.dataset.reviewName || '');
    if(reviewModalTitle) reviewModalTitle.textContent=card.dataset.reviewName || 'Отзыв';
    reviewModal.classList.add('is-open');
    reviewModal.setAttribute('aria-hidden','false');
    document.body.classList.add('modal-open');
  });
});

document.querySelectorAll('[data-review-close]').forEach(el=>{
  el.addEventListener('click',closeReviewModal);
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape') closeReviewModal();
});

// Floating welcome video — original-quality source assembled from small chunks
(() => {
  const box = document.getElementById('welcomeVideo');
  const video = document.getElementById('welcomeVideoPlayer');
  const close = document.getElementById('welcomeVideoClose');
  const sound = document.getElementById('welcomeVideoSound');
  if (!box || !video) return;

  let closed = false;
  let objectUrl = '';
  const parts = [
    'video-hq.part00',
    'video-hq.part01',
    'video-hq.part02',
    'video-hq.part03'
  ];

  box.classList.add('is-visible');

  Promise.all(parts.map(async (url) => {
    const response = await fetch(url, {cache: 'force-cache'});
    if (!response.ok) throw new Error(`Video chunk failed: ${url}`);
    return response.arrayBuffer();
  }))
    .then((buffers) => {
      if (closed) return;
      const blob = new Blob(buffers, {type: 'video/mp4'});
      objectUrl = URL.createObjectURL(blob);
      video.src = objectUrl;
      video.load();
      return video.play();
    })
    .catch(() => {
      if (!closed) {
        video.src = 'assets/intro-popup.mp4';
        video.load();
        video.play().catch(() => {});
      }
    });

  close?.addEventListener('click', () => {
    closed = true;
    box.classList.remove('is-visible');
    video.pause();
    if (objectUrl) URL.revokeObjectURL(objectUrl);
  });

  sound?.addEventListener('click', () => {
    video.muted = !video.muted;
    sound.textContent = video.muted ? '🔇 Звук' : '🔊 Звук';
    sound.setAttribute('aria-label', video.muted ? 'Включить звук' : 'Выключить звук');
    if (video.paused && video.src) video.play().catch(() => {});
  });
})();